//! 🧪️ Actual field7 tokens preserve final scalar pointers and paid closure at every original octet cut.
use super::*;
use pack::record::RetainedRecordBodySourceDecode;
use pack::record::RetainedRecordBodyToken;
use pack::record::RetainedValueRole;
use pack::record::RetainedValueToken;
use semio_framework_tool_run_tick_wire::testkit::entity_column_receiving::Phase;
use semio_framework_value::RetainedCloneGrant;
use semio_framework_value::RetainedCloneProgress;
use protocol::codec::{OriginalWireSourceIdentity,RetainedWireByteSource};
use crate::ToolRunReceivingLimits;
type Receipt=Option<(RetainedCloneGrant,RetainedCloneProgress)>;
struct Pages<'a>(&'a[u8]);
impl RetainedWireByteSource for Pages<'_>{fn original_source_identity(&self)->OriginalWireSourceIdentity{OriginalWireSourceIdentity{range_start:0,address:self.0.as_ptr()as usize,extent:self.0.len(),authority:Some((42,7))}}fn byte_at(&self,index:usize)->Option<u8>{self.0.chunks(7).nth(index/7)?.get(index%7).copied()}}
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(v,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(v,(h.requested_bytes,h.released_bytes))}
fn received(g:RetainedCloneGrant,p:RetainedCloneProgress,r:Receipt,h:(usize,usize)){assert_eq!(r,Some((g,p)));assert!(p.fits(g));assert_eq!((p.retained_capacity_bytes,p.released_bytes),h)}
#[test]
fn original_native_tick_entity_column_preserves_final_cells_and_every_octet_interruption(){
 let fixture:serde_json::Value=serde_json::from_str(crate::fixture_text("🎞️tick/🛬️receive/🔢️entities/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:17,maximum_capacity_bytes:65536,maximum_release_bytes:262144,maximum_depth:64};let m=RetainedCloneGrant{maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,..g};
 for row in fixture["cases"].as_array().unwrap(){let entities=row["entities"].as_array().unwrap();let hex=row["hex"].as_str().unwrap();let bytes:Vec<u8>=std::iter::once(0).chain(std::iter::once(1)).chain([7,8,(hex.len()/2)as u8]).chain(hex.as_bytes().chunks_exact(2).map(|b|u8::from_str_radix(std::str::from_utf8(b).unwrap(),16).unwrap())).collect();let source=Pages(&bytes);
  for cut in row["interruptAfter"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize)).chain(std::iter::once(None)){
   let(mut lower,h)=observe(||RetainedRecordBodySourceDecode::admit(&source,(0,bytes.len()),ToolRunReceivingLimits::REPORTS.tick.record_body(),g).unwrap().unwrap());let mut physical=h;let r=lower.take_receipt().unwrap();received(g,r.1,Some(r),h);
   let((mut frame,p),h)=observe(||ToolRunNativeTickPreparation::admit(&lower,ToolRunReceivingLimits::REPORTS,g).unwrap().unwrap());received(g,p,frame.take_receipt(),h);physical.0+=h.0;physical.1+=h.1;let address=frame.native_address().unwrap();for _ in 0..9{let(p,h)=observe(||frame.initialize_header_step(m).unwrap());received(m,p,frame.take_receipt(),h)}
   for denied in[RetainedCloneGrant{maximum_items:0,..m},RetainedCloneGrant{maximum_depth:1,..m}]{let(r,h)=observe(||ToolRunEntityColumnReceiving::admit(&lower,&mut frame,denied).unwrap());assert!(r.is_none());assert_eq!(h,(0,0))}
   let((mut column,p),h)=observe(||ToolRunEntityColumnReceiving::admit(&lower,&mut frame,m).unwrap().unwrap());received(m,p,column.take_receipt(&lower,&mut frame).unwrap(),h);let mut copied=0;let mut pending=None;let mut pointers=Vec::new();let mut turns=0;
   while cut.is_none_or(|stop|copied<stop)&&!column.is_complete(){turns+=1;assert!(turns<10000);let d=column.reserve_demands(&lower,&frame).unwrap();if d.depth>0{for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:d.depth-1,..g},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g}]{let(r,h)=observe(||column.reserve_step(&lower,&mut frame,denied).unwrap());assert!(r.is_none());assert_eq!(h,(0,0))}let(p,h)=observe(||column.reserve_step(&lower,&mut frame,g).unwrap().unwrap());received(g,p,column.take_receipt(&lower,&mut frame).unwrap(),h);physical.0+=h.0;physical.1+=h.1;continue}
    if column.phase==Phase::Commit{let(p,h)=observe(||column.commit_step(&lower,&mut frame,m).unwrap().unwrap());assert!(column.commit_step(&lower,&mut frame,m).unwrap().is_none());received(m,p,column.take_receipt(&lower,&mut frame).unwrap(),h);let native=frame.testkit_entity_column(&lower,address).unwrap();pointers.push(native.backing_ptr(native.len()-1).unwrap());continue}
    if pending.is_none(){if lower.token().is_some(){let(ok,h)=observe(||lower.take_token_into(&mut pending,g).unwrap());assert!(ok);let r=lower.take_receipt().unwrap();received(g,r.1,Some(r),h);}else{let(_,h)=observe(||lower.step(&source,g).unwrap());let r=lower.take_receipt().unwrap();received(g,r.1,Some(r),h);physical.0+=h.0;physical.1+=h.1;continue}}
    if !matches!(pending,Some(RetainedRecordBodyToken::Value(RetainedValueToken::Unsigned{role:RetainedValueRole::FieldId,..}|RetainedValueToken::Tag{..}|RetainedValueToken::Unsigned{role:RetainedValueRole::BytesLength,..}|RetainedValueToken::Byte(_)))){pending.take();continue}
    let offered=pending;for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:1,..g}]{let(r,h)=observe(||column.receive(&lower,&frame,&mut pending,denied).unwrap());assert!(r.is_none());assert_eq!(pending,offered);assert_eq!(h,(0,0))}if matches!(pending,Some(RetainedRecordBodyToken::Value(RetainedValueToken::Byte(_)))){assert!(column.receive(&lower,&frame,&mut pending,m).unwrap().is_none());assert_eq!(pending,offered)}let(p,h)=observe(||column.receive(&lower,&frame,&mut pending,g).unwrap().unwrap());assert!(column.receive(&lower,&frame,&mut pending,g).unwrap().is_none());received(g,p,column.take_receipt(&lower,&mut frame).unwrap(),h);copied+=p.copied_bytes;assert_eq!(frame.native_address(),Some(address));let native=frame.testkit_entity_column(&lower,address).unwrap();for(index,pointer)in pointers.iter().enumerate(){assert_eq!(native.backing_ptr(index),Some(*pointer));assert_eq!(native[index],entities[index].as_u64().unwrap())}
   }
   if cut.is_none(){assert!(column.is_complete());assert_eq!(copied,hex.len()/2);let native=frame.testkit_entity_column(&lower,address).unwrap();assert_eq!(native.len(),entities.len());assert_eq!(native.capacity(),entities.len());for(index,entity)in entities.iter().enumerate(){assert_eq!(native[index],entity.as_u64().unwrap())}}
   frame.cancel();assert_eq!(frame.close_demands(),Default::default());assert!(frame.close_step(g).is_none());column.cancel();for denied in[RetainedCloneGrant{maximum_items:0,..m},RetainedCloneGrant{maximum_depth:1,..m}]{let(r,h)=observe(||column.close_step(&lower,&mut frame,denied).unwrap());assert!(r.is_none());assert_eq!(h,(0,0))}let(p,h)=observe(||column.close_step(&lower,&mut frame,m).unwrap().unwrap());assert!(frame.close_step(g).is_none());received(m,p,column.take_receipt(&lower,&mut frame).unwrap(),h);assert!(column.terminal_is_empty());let(_,h)=observe(||drop(column));assert_eq!(h,(0,0));
   while !frame.terminal_is_empty(){let d=frame.close_demands();for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:d.depth-1,..g}]{let(r,h)=observe(||frame.close_step(denied));assert!(r.is_none());assert_eq!(h,(0,0))}if d.release_bytes>0{let(r,h)=observe(||frame.close_step(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g}));assert!(r.is_none());assert_eq!(h,(0,0))}let(p,h)=observe(||frame.close_step(g).unwrap());received(g,p,frame.take_receipt(),h);physical.0+=h.0;physical.1+=h.1}
   lower.cancel();while !lower.terminal_is_empty(){if lower.token().is_some(){pending.take();assert!(lower.take_token_into(&mut pending,g).unwrap());lower.take_receipt().unwrap();pending.take();}let(_,h)=observe(||lower.close_step(g).unwrap());let r=lower.take_receipt().unwrap();received(g,r.1,Some(r),h);physical.0+=h.0;physical.1+=h.1}assert_eq!(physical.0,physical.1);let(_,h)=observe(||{drop(frame);drop(lower)});assert_eq!(h,(0,0));
  }
 }
}
#[test]
fn original_native_tick_entity_column_counts_actual_source_allocation_before_final_column_birth(){
 let law:serde_json::Value=serde_json::from_str(crate::fixture_text("🎞️tick/🛬️receive/🔢️entities/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let bytes=[0,1,7,8,8,42,0,0,0,0,0,0,0];let source=Pages(&bytes);let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:17,maximum_capacity_bytes:65536,maximum_release_bytes:262144,maximum_depth:64};let m=RetainedCloneGrant{maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,..g};
 let(mut lower,h)=observe(||RetainedRecordBodySourceDecode::admit(&source,(0,bytes.len()),ToolRunReceivingLimits::REPORTS.tick.record_body(),g).unwrap().unwrap());let mut physical=h;let r=lower.take_receipt().unwrap();received(g,r.1,Some(r),h);let mut pending=None;
 for _ in 0..10000{if matches!(pending,Some(RetainedRecordBodyToken::Value(RetainedValueToken::Unsigned{role:RetainedValueRole::FieldId,value:7}))){break}pending.take();if lower.token().is_some(){assert!(lower.take_token_into(&mut pending,g).unwrap());let r=lower.take_receipt().unwrap();received(g,r.1,Some(r),(0,0));}else{let(_,h)=observe(||lower.step(&source,g).unwrap());let r=lower.take_receipt().unwrap();received(g,r.1,Some(r),h);physical.0+=h.0;physical.1+=h.1}}
 assert!(pending.is_some());assert_eq!(lower.allocated_bytes(),law["allocationCeiling"]["sourceBytes"].as_u64().unwrap()as usize);assert_eq!(ToolRunNativeTickPreparation::birth_bytes(),law["allocationCeiling"]["frameBytes"].as_u64().unwrap()as usize);let mut limits=ToolRunReceivingLimits::REPORTS;limits.tick.maximum_total_allocation_bytes=law["allocationCeiling"]["maximumTotalAllocationBytes"].as_u64().unwrap()as u32;limits.tick.maximum_cursor_allocation_bytes=law["allocationCeiling"]["maximumCursorAllocationBytes"].as_u64().unwrap()as u32;
 let mut too_small=limits;too_small.tick.maximum_total_allocation_bytes-=1;let(r,h)=observe(||ToolRunNativeTickPreparation::admit(&lower,too_small,g));assert!(r.is_err());assert_eq!(h,(0,0));let((mut frame,p),h)=observe(||ToolRunNativeTickPreparation::admit(&lower,limits,g).unwrap().unwrap());received(g,p,frame.take_receipt(),h);physical.0+=h.0;physical.1+=h.1;for _ in 0..9{let(p,h)=observe(||frame.initialize_header_step(m).unwrap());received(m,p,frame.take_receipt(),h)}let((mut column,p),h)=observe(||ToolRunEntityColumnReceiving::admit(&lower,&mut frame,m).unwrap().unwrap());received(m,p,column.take_receipt(&lower,&mut frame).unwrap(),h);
 for _ in 0..10000{if column.phase==Phase::Bytes{break}if pending.is_none(){if lower.token().is_some(){assert!(lower.take_token_into(&mut pending,g).unwrap());let r=lower.take_receipt().unwrap();received(g,r.1,Some(r),(0,0));}else{let(_,h)=observe(||lower.step(&source,g).unwrap());let r=lower.take_receipt().unwrap();received(g,r.1,Some(r),h);physical.0+=h.0;physical.1+=h.1;continue}}let(p,h)=observe(||column.receive(&lower,&frame,&mut pending,m).unwrap().unwrap());received(m,p,column.take_receipt(&lower,&mut frame).unwrap(),h)}assert!(column.phase==Phase::Bytes);let address=frame.native_address().unwrap();let(r,h)=observe(||column.reserve_step(&lower,&mut frame,g));assert!(r.is_err());assert_eq!(h,(0,0));assert!(column.receipt().is_none());assert!(frame.testkit_entity_column(&lower,address).unwrap().terminal_is_empty());
 frame.cancel();column.cancel();let(p,h)=observe(||column.close_step(&lower,&mut frame,m).unwrap().unwrap());received(m,p,column.take_receipt(&lower,&mut frame).unwrap(),h);assert!(column.terminal_is_empty());while !frame.terminal_is_empty(){let(p,h)=observe(||frame.close_step(g).unwrap());received(g,p,frame.take_receipt(),h);physical.0+=h.0;physical.1+=h.1}lower.cancel();while !lower.terminal_is_empty(){if lower.token().is_some(){pending.take();assert!(lower.take_token_into(&mut pending,g).unwrap());lower.take_receipt().unwrap();pending.take();}let(_,h)=observe(||lower.close_step(g).unwrap());let r=lower.take_receipt().unwrap();received(g,r.1,Some(r),h);physical.0+=h.0;physical.1+=h.1}assert_eq!(physical.0,physical.1);let(_,h)=observe(||{drop(column);drop(frame);drop(lower)});assert_eq!(h,(0,0));
}
